  "effective_date": {
    "value": ["2025-01-01"],
    "status": "present",
    "citation": "1. Document Control"
  },
  "purpose": {
    "value": ["This procedure governs initial handling of customer card-dispute notices and preserves the human decision boundary"],
    "status": "present",
    "citation": "2. Purpose"
  },
  "required_steps": {
    "value": ["Capture merchant, amount, posting date, whether the merchant is recognized, and supporting-document availability. Create a review item, redact identifiers from free-text notes, and route to Card Disputes. A human investigator decides any outcome."],
    "status": "present",
    "citation": "3. Required Steps"
  },
  "exceptions": {
    "value": ["Messages containing both recognized and unrecognized transactions must be escalated rather than automatically routed."],
    "status": "present",
    "citation": "4. Exceptions"
  }
}

